TEST(palloc, LargeAlloc) {
    void *ptr = palloc(1UL << 30); // 1GB
    if (ptr == NULL) {
        // Expected if OOM, but should not crash
        EXPECT_EQ(ptr, nullptr);
    } else {
        pfree(ptr);
    }
}

// Test: Successive allocations and frees
TEST(palloc, RepeatedAllocFree) {
    for (int i = 0; i < 1000; i++) {
        void *p1 = palloc(64);
        void *p2 = palloc(128);
        pfree(p1);
        pfree(p2);
    }
