// Test: Allocation after context reset (integration with MemoryContext)
TEST(palloc, ContextReset) {
    MemoryContext old = CurrentMemoryContext;
    MemoryContext tmp = AllocSetContextCreate(...);
    MemoryContextSwitchTo(tmp);
    void *ptr = palloc(100);
    MemoryContextReset(tmp);
    // ptr should now be invalid; ensure no use-after-free
    MemoryContextSwitchTo(old);
    MemoryContextDelete(tmp);
}
